//! A sine lookup table, built at compile time.
//!
//! `sin` is one of the expensive calls the audio thread avoids. The table
//! is filled by a `const fn` (a Taylor series evaluated in `f64`), so it
//! is generated by our own code when the crate compiles and costs nothing
//! at run time. Reading it with linear interpolation is accurate to about
//! 1e-6, far below anything audible.

use std::f64::consts::{FRAC_PI_2, PI, TAU};

/// Table steps per cycle. Linear interpolation over a step of `2π/2048`
/// is off by at most `(2π/2048)²/8 ≈ 1.2e-6`.
const SIZE: usize = 2048;

/// One cycle of sine, plus the first sample again at the end, so an
/// interpolated read never wraps.
static TABLE: [f32; SIZE + 1] = table();

const fn table() -> [f32; SIZE + 1] {
    let mut table = [0.0f32; SIZE + 1];
    let mut i = 0;
    while i <= SIZE {
        table[i] = taylor_sine(TAU * i as f64 / SIZE as f64) as f32;
        i += 1;
    }
    table
}

/// `sin(x)` for `x` in `[0, 2π]`, folded into `[-π/2, π/2]` where the
/// series converges fastest.
const fn taylor_sine(x: f64) -> f64 {
    let mut x = if x > PI { x - TAU } else { x };
    if x > FRAC_PI_2 {
        x = PI - x;
    } else if x < -FRAC_PI_2 {
        x = -PI - x;
    }
    let square = x * x;
    let mut term = x;
    let mut sum = x;
    // Terms to x^25: the next is below 1e-17 at π/2.
    let mut n = 1;
    while n <= 12 {
        term *= -square / ((2 * n) * (2 * n + 1)) as f64;
        sum += term;
        n += 1;
    }
    sum
}

/// The sine of `phase` cycles (`sin(2π·phase)`). Any phase works; whole
/// cycles are dropped first.
#[inline]
pub fn sine(phase: f32) -> f32 {
    let phase = phase - phase.floor();
    let position = phase * SIZE as f32;
    // A phase a hair below a whole cycle can round up to exactly one.
    let index = (position as usize).min(SIZE - 1);
    let fraction = position - index as f32;
    let (a, b) = (TABLE[index], TABLE[index + 1]);
    a + (b - a) * fraction
}

/// The cosine of `phase` cycles.
#[inline]
pub fn cosine(phase: f32) -> f32 {
    sine(phase + 0.25)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_matches_the_library_sine() {
        for (i, &entry) in TABLE.iter().enumerate() {
            let exact = (TAU * i as f64 / SIZE as f64).sin();
            assert!((f64::from(entry) - exact).abs() < 1e-7, "entry {i}");
        }
    }

    #[test]
    fn interpolated_reads_are_accurate_everywhere() {
        let mut worst = 0.0f64;
        for i in 0..100_003 {
            let phase = i as f32 / 100_003.0 * 3.0 - 1.0;
            let exact = (TAU * f64::from(phase)).sin();
            worst = worst.max((f64::from(sine(phase)) - exact).abs());
            let exact = (TAU * f64::from(phase)).cos();
            worst = worst.max((f64::from(cosine(phase)) - exact).abs());
        }
        assert!(worst < 2e-6, "worst error {worst}");
    }

    #[test]
    fn a_phase_just_below_a_whole_cycle_stays_in_the_table() {
        assert!(sine(-1e-9).abs() < 1e-5);
        assert!(sine(0.999_999_99).abs() < 1e-5);
    }
}
